//! The SQL the copy writes, byte for byte as it was before the writers took a dialect: the
//! expected texts were written by the functions as they were then, over the same inputs.

use super::*;

/// The SQL the copy writes for tricky values and names, every function and kind.
fn golden_outputs() -> Vec<String> {
    let kinds = [
        Kind::Text,
        Kind::Number,
        Kind::Bool,
        Kind::Json,
        Kind::Array(Element::Number),
        Kind::Array(Element::Text),
        Kind::Array(Element::Bool),
        Kind::Array(Element::Json),
    ];
    let values: &[Option<&str>] = &[
        None,
        Some(""),
        Some("O'Reilly"),
        Some("''"),
        Some("it's \"quoted\""),
        Some("back\\slash \\\\ \\x00ff \\n"),
        Some("tab\there\nnew\rline \u{1} \u{1b}[31m \u{7f} \u{85}"),
        Some("陳大文 🐘 👩‍👩‍👧 é"),
        Some("NaN"),
        Some("Infinity"),
        Some("-Infinity"),
        Some("-0"),
        Some("-0.0e5"),
        Some("0"),
        Some("12"),
        Some("-3.5"),
        Some(".5"),
        Some("5."),
        Some("1e10"),
        Some("-2.5E-3"),
        Some("+1"),
        Some("1,000"),
        Some("$1.00"),
        Some("0x1F"),
        Some("true"),
        Some("false"),
        Some("t"),
        Some("f"),
        Some("TRUE"),
        Some("null"),
        Some("NULL"),
        Some(r#"{"a": [1, 2], "b": "it's"}"#),
        Some(r#"{"k": "back\\slash"}"#),
        Some("not json"),
        Some("{1,2}"),
        Some("{{1,2},{3,NULL}}"),
        Some(r#"{"a\"b",NULL,"c d",'e'}"#),
        Some("{t,f}"),
        Some("[0:1]={7,8}"),
        Some("2024-02-29 12:34:56.789+09"),
        Some("\\x0102ff"),
    ];
    let names = ["id", "Mixed Case", "select", "user", "order items", "t\"x", "", "ID", "名前", "a'b"];
    let mut out = Vec::new();
    for k in kinds {
        for v in values {
            out.push(sql_value(PG, k, *v));
        }
        let rows: Vec<Row> = values.iter().map(|v| vec![*v]).collect();
        out.push(format!("{:?}", sql_in(PG, &[col("c", k)], &rows)));
    }
    // One column per name, each of every kind in turn.
    let columns: Vec<Column> = names.iter().zip(kinds.iter().cycle()).map(|(n, k)| col(n, *k)).collect();
    let rows: Vec<Row> = values
        .iter()
        .enumerate()
        .map(|(i, _)| (0..columns.len()).map(|c| values[(i + c) % values.len()]).collect())
        .collect();
    for (schema, table) in [("public", "users"), ("My Schema", "order items"), ("select", "t\"x"), ("", "名前")] {
        for overriding in [false, true] {
            let target = Target::Table { schema, name: table, columns: names.to_vec(), overriding };
            out.push(sql_insert(PG, &target, &columns, &rows));
            let mut w = Writer::new(Format::Sql(PG, target.clone()), &columns);
            for part in rows.chunks(7) {
                w.rows(part);
            }
            out.push(w.finish());
        }
        let update = UpdateTarget {
            schema,
            name: table,
            set: (2..names.len()).map(|i| (i, names[i])).collect(),
            keys: vec![(0, names[0]), (1, names[1])],
        };
        out.push(sql_update(PG, &update, &columns, &rows));
        let mut w = Writer::new(Format::Update(PG, update.clone()), &columns);
        for part in rows.chunks(5) {
            w.rows(part);
        }
        out.push(w.finish());
    }
    out.push(sql_insert(PG, &Target::Unknown, &columns, &rows));
    out.push(sql_insert(PG, &Target::Unknown, &columns, &[]));
    out
}

#[test]
fn postgres_sql_is_what_it_was() {
    let out = golden_outputs();
    assert_eq!(out.len(), EXPECTED.len());
    for (i, (got, want)) in out.iter().zip(EXPECTED).enumerate() {
        assert_eq!(got, want, "output {i}");
    }
}

